mapper.select:
SELECT gcc.config_id, gcc.config_name, gcc.user_type, CASE gcc.user_type WHEN 1 THEN '采购员' WHEN 2 THEN '管理员' ELSE '未知' END AS user_type_name, gcc.commission_type, CASE gcc.commission_type WHEN 1 THEN '固定金额' WHEN 2 THEN '百分比' ELSE '未知' END AS commission_type_name, gcc.commission_value, gcc.min_commission, gcc.max_commission, gcc.effective_time, gcc.expiry_time, gcc.status, CASE gcc.status WHEN 0 THEN '禁用' WHEN 1 THEN '启用' ELSE '未知' END AS status_name, gcc.remark, gcc.created_by, gcc.created_at, gcc.updated_by, gcc.updated_at FROM global_commission_config gcc WHERE gcc.is_deleted = 0
AND gcc.user_type = #{userType}
AND gcc.status = #{status}
AND (gcc.config_name LIKE CONCAT('%', #{keyword}, '%') OR gcc.remark LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY gcc.created_at DESC

